changeSet.sql:
DO $do$ BEGIN LOCK TABLE ingestion_task IN ACCESS EXCLUSIVE MODE;
IF EXISTS ( SELECT 1 FROM ingestion_task WHERE nullif(btrim(dbt_model_selector), '') IS NOT NULL OR nullif(btrim(dbt_dag_selector), '') IS NOT NULL ) THEN RAISE EXCEPTION 'INGESTION_DIRECT_DBT_RETIREMENT_BLOCKED: non-empty selector appeared after the initial precondition check'; END IF;
IF EXISTS ( SELECT 1 FROM pg_constraint constraint_definition WHERE constraint_definition.conrelid = 'ingestion_task'::regclass AND EXISTS ( SELECT 1 FROM unnest(constraint_definition.conkey) constrained_column(attnum) JOIN pg_attribute attribute_definition ON attribute_definition.attrelid = constraint_definition.conrelid AND attribute_definition.attnum = constrained_column.attnum WHERE attribute_definition.attname IN ('dbt_model_selector', 'dbt_dag_selector') ) ) OR EXISTS ( SELECT 1 FROM pg_index index_definition WHERE index_definition.indrelid = 'ingestion_task'::regclass AND EXISTS ( SELECT 1 FROM unnest(index_definition.indkey::smallint[]) indexed_column(attnum) JOIN pg_attribute attribute_definition ON attribute_definition.attrelid = index_definition.indrelid AND attribute_definition.attnum = indexed_column.attnum WHERE attribute_definition.attname IN ('dbt_model_selector', 'dbt_dag_selector') ) ) OR EXISTS ( SELECT 1 FROM pg_depend dependency JOIN pg_rewrite rewrite_rule ON rewrite_rule.oid = dependency.objid JOIN pg_class dependent_view ON dependent_view.oid = rewrite_rule.ev_class JOIN pg_attribute source_column ON source_column.attrelid = dependency.refobjid AND source_column.attnum = dependency.refobjsubid WHERE dependency.refobjid = 'ingestion_task'::regclass AND source_column.attname IN ('dbt_model_selector', 'dbt_dag_selector') AND dependent_view.relkind IN ('v', 'm') ) THEN RAISE EXCEPTION 'INGESTION_DIRECT_DBT_RETIREMENT_SCHEMA_UNEXPECTED: selector dependency appeared after the initial precondition check'; END IF; END $do$;

rollback.sql:
DO $$
BEGIN
    RAISE EXCEPTION 'ROLLBACK_BLOCKED_INGESTION_DIRECT_DBT_RETIREMENT_FORWARD_ONLY: recovery requires a new forward changeset';
END $$;
